BEGIN TRANSACTION;
CREATE TABLE "albums" (
                        album_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        album_name TEXT NOT NULL,
                        artist TEXT NOT NULL,
                        country TEXT,
                        region TEXT,
                        genre TEXT,
                        rating REAL,
                        description TEXT,
                        is_compilation INTEGER DEFAULT 0,
                        first_listen_date TEXT,
                        total_listen_count INTEGER DEFAULT 1,
                        release_company TEXT,
                        cover_image_url TEXT,
                        duration TEXT,
                        composition_score REAL,
                        lyrics_meaning_score REAL,
                        creativity_score REAL,
                        arrangement_score REAL,
                        vocal_performance_score REAL,
                        instrumental_performance_score REAL,
                        sincerity_score REAL,
                        subjective_score REAL,
                        overall_score REAL,
                        release_year TEXT,
                        style TEXT,
                        producer TEXT
, artist_id INTEGER, genre_id INTEGER, style_id INTEGER);
CREATE TABLE albums_2024 (
                        album_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        album_name TEXT NOT NULL,
                        artist TEXT NOT NULL,
                        country TEXT,
                        region TEXT,
                        genre TEXT,
                        rating REAL,
                        description TEXT,
                        is_compilation INTEGER DEFAULT 0,
                        first_listen_date TEXT,
                        total_listen_count INTEGER DEFAULT 1,
                        release_company TEXT,
                        cover_image_url TEXT,
                        duration TEXT,
                        composition_score REAL,
                        lyrics_meaning_score REAL,
                        creativity_score REAL,
                        arrangement_score REAL,
                        vocal_performance_score REAL,
                        instrumental_performance_score REAL,
                        sincerity_score REAL,
                        subjective_score REAL,
                        overall_score REAL,
                        release_year TEXT,
                        style TEXT,
                        producer TEXT
);
CREATE TABLE albums_2025 (
                        album_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        album_name TEXT NOT NULL,
                        artist TEXT NOT NULL,
                        country TEXT,
                        region TEXT,
                        genre TEXT,
                        rating REAL,
                        description TEXT,
                        is_compilation INTEGER DEFAULT 0,
                        first_listen_date TEXT,
                        total_listen_count INTEGER DEFAULT 1,
                        release_company TEXT,
                        cover_image_url TEXT,
                        duration TEXT,
                        composition_score REAL,
                        lyrics_meaning_score REAL,
                        creativity_score REAL,
                        arrangement_score REAL,
                        vocal_performance_score REAL,
                        instrumental_performance_score REAL,
                        sincerity_score REAL,
                        subjective_score REAL,
                        overall_score REAL,
                        release_year TEXT,
                        style TEXT,
                        producer TEXT
);
CREATE TABLE albums_2026 (
                        album_id INTEGER PRIMARY KEY AUTOINCREMENT,
                        album_name TEXT NOT NULL,
                        artist TEXT NOT NULL,
                        country TEXT,
                        region TEXT,
                        genre TEXT,
                        rating REAL,
                        description TEXT,
                        is_compilation INTEGER DEFAULT 0,
                        first_listen_date TEXT,
                        total_listen_count INTEGER DEFAULT 1,
                        release_company TEXT,
                        cover_image_url TEXT,
                        duration TEXT,
                        composition_score REAL,
                        lyrics_meaning_score REAL,
                        creativity_score REAL,
                        arrangement_score REAL,
                        vocal_performance_score REAL,
                        instrumental_performance_score REAL,
                        sincerity_score REAL,
                        subjective_score REAL,
                        overall_score REAL,
                        release_year TEXT,
                        style TEXT,
                        producer TEXT
);
CREATE TABLE artists (
        artist_id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE,
        name_variants TEXT DEFAULT '[]',
        country TEXT DEFAULT '',
        formed_year INTEGER,
        is_active INTEGER DEFAULT 1,
        total_listen_count INTEGER DEFAULT 0,
        avg_rating REAL DEFAULT 0.0,
        album_count INTEGER DEFAULT 0,
        created_at TEXT DEFAULT (datetime('now', 'localtime'))
    );
CREATE TABLE genres (
        genre_id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE
    );
CREATE TABLE listen_history (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        album_id INTEGER NOT NULL,
        listen_date TEXT,
        listen_year INTEGER NOT NULL,
        notes TEXT DEFAULT '',
        source TEXT DEFAULT '',
        FOREIGN KEY (album_id) REFERENCES albums(album_id)
    );
CREATE TABLE styles (
        style_id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL UNIQUE
    );
CREATE INDEX idx_albums_artist_id ON albums(artist_id);
CREATE INDEX idx_lh_year ON listen_history(listen_year);
CREATE INDEX idx_lh_album ON listen_history(album_id);
DELETE FROM "sqlite_sequence";
COMMIT;
