INSERT INTO "albums" VALUES(376,'Ultra','Depeche Mode','英国','埃塞克斯','Alternative Rock, Synthpop',3.71,'《Ultra》是 Depeche Mode 于1997年4月14日发行的第九张录音室专辑，标志着乐队在成员变动与戒毒恢复后的重生。专辑融合了工业摇滚、氛围流行与黑暗电子元素，展现出深沉、内省与都市感的氛围。代表作包括《Barrel of a Gun》《It’s No Good》《Home》《Useless》等，Martin Gore 与 Dave Gahan 分别在创作与演唱上展现出成熟与情感张力。制作方面由 Tim Simenon 操刀，音效精致，层次丰富。',0,'2025-10-27',1,'Mute唱片','covers/376-Depeche_Mode-Ultra.jpg','60:04:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1997-04-14','Rock,Electronic','Tim Simenon',49,201,8);
INSERT INTO "albums" VALUES(377,'Toxicity','System of a Down','美国','加利福尼亚州','Alternative Metal, Nu Metal, Avant-Garde Metal',4.03,'《Toxicity》是 System of a Down 于2001年9月4日发行的第二张录音室专辑，融合了另类金属、前卫金属与中东音乐元素，风格激进而多变。专辑以政治与社会议题为核心，歌词尖锐，编曲富于戏剧性与节奏张力。代表作包括《Chop Suey!》《Toxicity》《Aerials》，展现出乐队在旋律与爆发力之间的平衡。制作由 Rick Rubin 与 Daron Malakian 操刀，音效清晰有力，成为21世纪初金属乐的标志性作品之一。',0,'2025-10-27',1,'American唱片','covers/377-System_of_a_Down-Toxicity.jpg','44:01:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2001-09-04','Metal','Rick Rubin, Daron Malakian',135,202,16);
INSERT INTO "albums" VALUES(378,'Frizzle Fry','Primus','美国','加利福尼亚州','Funk Metal, Experimental Rock, Avant-Garde Metal',3.83,'《Frizzle Fry》是 Primus 于1990年5月发行的首张录音室专辑，融合了放克金属、噪音摇滚与数学摇滚元素，风格怪诞、幽默、技术性强。主唱兼贝斯手 Les Claypool 凭借极具特色的弹奏风格与讽刺歌词奠定了乐队的标志性声音。代表作包括《John the Fisherman》《Too Many Puppies》《To Defy the Laws of Tradition》，其中《Too Many Puppies》被认为是对美国军事工业的讽刺。专辑整体节奏跳跃、结构复杂，展现出 Primus 独树一帜的音乐美学。',0,'2025-10-27',1,'Caroline唱片','covers/378-Primus-Frizzle_Fry.jpg','51:17:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1990-05-01','Metal','Primus, Matt Winegar',118,203,16);
INSERT INTO "albums" VALUES(379,'To Pimp a Butterfly','Kendrick Lamar','美国','加利福尼亚州','Conscious Hip Hop, Jazz Rap, Neo-Soul, Funk, Poetry',4.38,'《To Pimp a Butterfly》是 Kendrick Lamar 于2015年3月15日发行的第三张录音室专辑，以其深刻的政治性、诗意的歌词和丰富的音乐性被誉为当代最具影响力的嘻哈作品之一。专辑融合了爵士、放克、灵魂与说唱元素，探讨了黑人身份、社会不公、精神挣扎与自我救赎等议题。代表作包括《King Kunta》《Alright》《The Blacker the Berry》《How Much a Dollar Cost》等。制作阵容包括 Thundercat、Flying Lotus、Terrace Martin、Kamasi Washington 等，展现出极高的艺术水准与文化厚度。',0,'2025-10-27',2,'Top Dawg唱片','covers/379-Kendrick_Lamar-To_Pimp_a_Butterfly.jpg','78:51:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2015-03-15','Hip Hop','Anthony "Top Dawg" Tiffith, Dr. Dre, Sounwave, Terrace Martin',77,204,27);
INSERT INTO "albums" VALUES(380,'Masterpiece','Big Thief','美国','纽约','Indie Rock, Indie Folk, Americana, Folk Rock, Slacker Rock',3.71,'《Masterpiece》是 Big Thief 于2016年5月27日发行的首张录音室专辑，由 Adrianne Lenker 领衔创作，展现出情感浓烈、旋律细腻的独立摇滚风格。专辑融合了民谣与摇滚传统，歌词充满诗意与怀旧气息，描绘家庭、爱与自我探索等主题。代表曲目包括《Masterpiece》《Vegas》《Interstate》《Paul》《Real Love》等，制作由 Andrew Sarlo 操刀，录音于2015年7月1日至12日完成，发行方为 Saddle Creek 与 4AD。',0,'2025-10-27',1,'4AD','covers/380-Big_Thief-Masterpiece.jpg','37:16:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2016-05-27','Folk,Rock','Andrew Sarlo, James Krivchenia',21,205,24);
INSERT INTO "albums" VALUES(381,'Diamond Jubilee','Cindy Lee','加拿大','温哥华','Hypnagogic Pop, Psychedelic Pop',3.87,'Cindy Lee 的第七张录音室专辑，融合 Brill Building、迷幻流行、Lo-fi 独立摇滚等复古风格，呈现出浓厚的怀旧氛围与非二元性别视角。专辑时长超过两小时，共收录 32 首曲目，被誉为“私人压片”式的 DIY 音乐杰作，在 RateYourMusic 上获得极高评价。',0,'2024-03-29',1,'Superior Viaduct','covers/381-Cindy_Lee-Diamond_Jubilee.jpg','122:09:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2024-03-29','Rock','Patrick Flegel, Steven Lind',37,206,1);
INSERT INTO "albums" VALUES(382,'Teens of Denial','Car Seat Headrest','美国','弗吉尼亚州','Indie Rock, Power Pop, Garage Rock Revival, Art Rock',3.91,'Car Seat Headrest 于 2016 年推出的录音室专辑，由 Matador 唱片发行。专辑以青少年成长、精神健康、药物、孤独与自我怀疑等主题为核心，融合激烈的吉他、密集的编曲与诗意歌词，展现出强烈的情绪张力与哲思色彩。被誉为“完美的独立摇滚蒸馏物”，在 RYM 上获得超过 2.5 万条评分，位列 2016 年第 10 名。',0,'2025-10-28',4,'Matador唱片','covers/382-Car_Seat_Headrest-Teens_of_Denial.jpg','70:05:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2016-05-20','Rock','Steve Fisk',31,207,1);
INSERT INTO "albums" VALUES(383,'Nervous Young Man','Car Seat Headrest','美国','弗吉尼亚州','Slacker Rock, Singer-Songwriter, Indietronica, Indie Folk, Noise Pop, Art Rock',3.83,'《Nervous Young Man》是 Car Seat Headrest 于 2013 年 8 月 23 日发行的双碟专辑，时长超过 2 小时，共收录 20 首曲目。专辑以 lo-fi 质感和极具情绪张力的歌词著称，涵盖青春焦虑、孤独、性取向、死亡、自我怀疑等主题，展现 Will Toledo 独立创作的高峰。被誉为“私人压片”式 DIY 音乐杰作，是其 Matador 唱片签约前最重要的作品之一。',0,'2025-10-28',3,'自发行','covers/383-Car_Seat_Headrest-Nervous_Young_Man.jpg','129:23:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2013-08-23','Rock','Will Toledo',31,208,1);
INSERT INTO "albums" VALUES(384,'Making a Door Less Open','Car Seat Headrest','美国','弗吉尼亚州','Indietronica, Indie Rock, Alternative Dance, Synthpop',2.85,'《Making a Door Less Open》是 Car Seat Headrest 于 2020 年 5 月 1 日发行的录音室专辑，由 Matador唱片 发行。专辑融合电子流行与另类摇滚元素，尝试打破既有风格界限，呈现出更为分裂与实验性的声音结构。尽管在乐迷间评价两极，但部分曲目如《Life Worth Missing》《Deadlines (Hostile)》仍被认为保留了乐队的情绪张力与创作特色。',0,'2025-10-28',1,'Matador唱片','covers/384-Car_Seat_Headrest-Making_a_Door_Less_Open.jpg','47:28:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-05-01','Rock,Pop','Will Toledo, Andrew Katz',31,209,17);
INSERT INTO "albums" VALUES(385,'Monomania','Car Seat Headrest','美国','弗吉尼亚州','Slacker Rock, Noise Pop, Indietronica, Singer-Songwriter, Bedroom Pop',3.78,'《Monomania》是 Car Seat Headrest 于 2012 年 8 月 1 日发行的录音室专辑，呈现出极具情绪张力的 lo-fi 音色与密集编曲。专辑围绕分手、抑郁、性取向、孤独与自我厌恶等主题展开，歌词充满愤怒、悲伤与渴望，被视为 Will Toledo 最具个人色彩的作品之一。代表曲目包括《Souls》《Anchorite (Love You Very Much)》《Times to Die》，在乐迷间拥有极高的共鸣度。',0,'2025-10-28',2,'自发行','covers/385-Car_Seat_Headrest-Monomania.jpg','61:18:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2012-08-01','Rock','Will Toledo',31,210,1);
INSERT INTO "albums" VALUES(386,'How to Leave Town','Car Seat Headrest','美国','弗吉尼亚州','Slacker Rock, Art Rock, Indietronica, Singer-Songwriter, Neo-Psychedelia, Space Rock Revival, Post-Rock',4.01,'概念性作品，内省、lo-fi、忧郁、孤独、焦虑、苦乐参半，带有存在主义与夜晚氛围，主题涉及异化、渴望、爱、自我厌恶、旅行、分手、友情与心理状态。',0,'2025-11-21',1,'自发行','covers/386-Car_Seat_Headrest-How_to_Leave_Town.jpg','62:28:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2014-10-31','Rock','Will Toledo',31,211,1);
INSERT INTO "albums" VALUES(387,'Document','R.E.M.','美国','乔治亚州','Alternative Rock, Jangle Pop, Post-Punk',3.72,'专辑具有政治性与旋律性，充满能量与抒情感，既有秋日牧歌般的氛围，也带有抽象与隐喻的表达。',0,'2011-12-19',2,'I.R.S. Records','covers/387-R.E.M.-Document.jpg','39:34:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1987-08-31','Rock,Pop,Punk','R.E.M.',121,212,42);
INSERT INTO "albums" VALUES(389,'Abbey Road','The Beatles','英国','利物浦','Pop Rock',4.3,'旋律感强烈、温暖、包含男声演唱与组曲形式，整体氛围积极、浪漫、兼具苦乐参半与夏日气息。',0,'2021-11-22',1,'苹果唱片','covers/389-The_Beatles-Abbey_Road.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1969-09-26','Rock,Pop','George Martin',137,1,17);
INSERT INTO "albums" VALUES(390,'越长大越孤单','牛奶咖啡','中国','大陆','Pop',3.0,NULL,0,'2008-03-19',1,'摩登天空唱片','covers/390-牛奶咖啡-越长大越孤单.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2008-03-19','Pop',NULL,242,147,2);
INSERT INTO "albums" VALUES(391,'夜郎溪','王齐铭','中国','大陆','	Memphis Rap',4.0,NULL,0,'2025-11-24',2,NULL,'covers/391-王齐铭-夜郎溪.jpg','22:33:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2023-11-05','Hip Hop',NULL,249,NULL,27);
INSERT INTO "albums" VALUES(392,'Pluto','郑宜农','中国','台湾','Pop',3.3,'《Pluto》展现了郑宜农优秀的谱曲能力，吸收不同曲风并结合创作好手，歌词直白却纯粹，展现真我面向。',0,'2025-11-25',2,NULL,'covers/392-郑宜农-Pluto.jpg','41:36:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2017-04-28','Pop',NULL,285,147,2);
INSERT INTO "albums" VALUES(393,'趣味小常识','九维','中国','大陆','Boom Bap, Hardcore Hip Hop',3.72,'《趣味小常识》是一张融合暴力、讽刺、都市批判与幽默的中文说唱专辑。九维以老北京痞气形象和犀利歌词刻画社会现实，既有早期直白粗粝的作品如《完犊子》《我想要》《冒着泡泡》，也有更抽象与深刻的主题如《枷锁-解锁》《权衡中》。专辑节奏简洁有力，采样与氛围感突出，展现了九维作为新一代北京地下嘻哈代表的才华。',0,'2025-11-25',1,'Undaloop唱片','covers/393-九维-趣味小常识.jpg',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-12-25','Hip Hop',NULL,166,214,27);
INSERT INTO "albums" VALUES(394,'Diaries','Chestnut Bakery','中国','大陆','Shoegaze, Dream Pop',3.57,'《Diaries》是Chestnut Bakery于2015年发行的首张全长专辑，融合了Shoegaze、Dream Pop与Indie Rock等元素。专辑以温暖、忧郁、氛围感十足的音色为特色，女声空灵而富有感情，旋律常伴随失真吉他与缓慢鼓点，营造出冬日般的内省氛围。代表曲目包括《Train》《Moon Palace》，展现了史诗般的音墙与情感张力。整体风格既有抒情的独立流行气质，也带有慢核的沉静与梦幻色彩。',0,'2025-11-25',2,'Boring唱片','covers/394-Chestnut_Bakery-Diaries.jpg','49:33:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2015-11-22','Rock,Pop',NULL,35,215,17);
INSERT INTO "albums" VALUES(395,'时间的歌','陈绮贞','中国','台湾','Indie Pop, Singer-Songwriter, Chamber Pop',3.01,'《时间的歌》是陈绮贞于2013年发行的专辑，延续其独立流行与创作歌手的风格。作品以温柔、抒情的旋律和细腻的歌词著称，融合室内流行的编曲质感，展现了她独特的音乐美学。专辑整体氛围安静而富有诗意，体现了陈绮贞在创作上的成熟与内省。',0,'2013-12-06',2,'索尼音乐','covers/395-陈绮贞-时间的歌.jpg','49:45:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2013-12-06','Pop',NULL,298,216,2);
INSERT INTO "albums" VALUES(396,'吉他手','陈绮贞','中国','台湾','Pop Rock, Singer-Songwriter',3.65,'《吉他手》是陈绮贞于2002年发行的代表作之一，融合了流行摇滚与独立流行、民谣流行等元素，带有梦幻与迷幻色彩。专辑氛围柔和、抒情，歌词常涉及孤独、怀旧、爱情与自我反思，展现了她独特的创作美学。作品既有轻快的旋律如《小步舞曲》，也有更具另类摇滚质感的曲目，整体风格在华语流行与独立音乐之间取得平衡。',0,'2012-01-25',1,'魔岩唱片','covers/396-陈绮贞-吉他手.jpg','47:15:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2002-08-01','Rock,Pop,Folk','林暐哲',298,19,43);
INSERT INTO "albums" VALUES(397,'枯萎颂','王忆灵','中国','大陆','Chamber Folk, Singer-Songwriter, Art Pop',3.72,'《枯萎颂》是王忆灵于2024年发行的专辑，融合室内民谣、艺术流行与前卫摇滚元素。专辑以钢琴与管弦乐为主线，搭配诗意歌词与多样化编曲，展现出丰富的情感层次。作品既有温柔抒情的旋律，也包含实验性的结构与跨风格的探索，整体氛围唯美而内省。',0,'2025-11-25',3,NULL,'covers/397-王忆灵-枯萎颂.jpg','56:03:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2024-08-07','Folk,Pop,Rock','王忆灵',245,217,44);
INSERT INTO "albums" VALUES(398,'Reckoning','R.E.M.','美国','乔治亚州','Jangle Pop, New Wave, Post-Punk, Paisley Underground',3.81,'《Reckoning》是R.E.M.于1984年发行的第二张录音室专辑，延续了首张专辑《Murmur》的清新与神秘氛围，但整体更为明快、直接。专辑包含经典曲目《So. Central Rain》《(Don’t Go Back To) Rockville》《Pretty Persuasion》等，展现了乐队早期标志性的吉他叮咚声与Michael Stipe独特的诗意歌词。该作被视为R.E.M.早期最具代表性的作品之一，奠定了他们在独立摇滚与主流摇滚之间的独特地位。',0,'2011-11-25',1,'I.R.S.唱片','covers/398-R.E.M.-Reckoning.jpg','37:27:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1984-04-16','Rock,Pop,Punk','Don Dixon, Mitch Easter',121,218,42);
INSERT INTO "albums" VALUES(399,'Arntor','Windir','挪威','维斯特兰','Melodic Black Metal, Viking Metal, Folk Metal',3.8,'Windir的第二张专辑，以史诗般的旋律和挪威民间传说为主题，融合了黑金属与民谣元素，展现出冷冽、神话与胜利的氛围。',0,'2025-12-01',1,'Head Not Found唱片','covers/399-Windir-Arntor.jpg','46:07:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1999-10-11','Metal,Folk','Valfar',1,219,45);
INSERT INTO "albums" VALUES(400,'Instrumentals','Adrianne Lenker','美国','印第安纳波利斯','Ambient, Contemporary Folk, Ambient Americana',3.57,'Adrianne Lenker在森林小屋即兴录制的双曲专辑，包含《Songs for Indigo》和《Mostly Chimes》，以吉他与自然雨声、风铃声营造出宁静、冥想与温暖的氛围。',0,'2025-12-01',1,'4AD','covers/400-Adrianne_Lenker-Instrumentals.jpg','37:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2020-10-22','Folk,Pop','Adrianne Lenker,Philip Weinrobe',4,220,18);
INSERT INTO "albums" VALUES(401,'Magical Mystery Tour','The Beatles','英国','利物浦','Psychedelic Pop, Pop Rock, Television Music',4.07,'《Magical Mystery Tour》是披头士于1967年11月27日发行的专辑，最初作为同名电视电影的原声带，后在美国以LP形式发行并加入单曲《Strawberry Fields Forever》《Penny Lane》《All You Need Is Love》等，逐渐被纳入官方唱片目录。专辑融合了幻想、迷幻与流行元素，包含《I Am the Walrus》《The Fool on the Hill》等经典曲目。',0,'2019-12-08',1,'Capitol唱片','covers/401-The_Beatles-Magical_Mystery_Tour.jpg','36:32:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1967-11-27','Rock,Pop','George Martin',137,221,17);
INSERT INTO "albums" VALUES(402,'Low','David Bowie','英国','伦敦','Art Rock',4.13,'《Low》是大卫·鲍伊于1977年1月14日发行的录音室专辑，由Tony Visconti制作，Brian Eno深度参与。专辑分为两部分：A面以碎片化的先锋流行与摇滚歌曲为主，如《Sound and Vision》《Be My Wife》，B面则是氛围化的电子器乐作品，如《Warszawa》《Subterraneans》。该作标志着鲍伊音乐风格的重大转折，融合了摇滚与电子实验，被视为“柏林三部曲”的开端，对后世的后朋克与电子音乐影响深远。',0,'2025-12-08',2,'RCA唱片','covers/402-David_Bowie-Low.jpg','38:26:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1977-01-14','Rock,Pop','Tony Visconti',43,112,17);
INSERT INTO "albums" VALUES(403,'Meat Is Murder','The Smiths','英国','曼彻斯特','Jangle Pop, Indie Pop',3.77,'《Meat Is Murder》是The Smiths于1985年2月11日发行的第二张录音室专辑，由Morrissey和Johnny Marr共同创作，Stephen Street担任工程师。专辑延续了乐队的独立摇滚风格，同时在歌词中加入了更强烈的政治与社会批判，如同名曲《Meat Is Murder》探讨素食主义与动物权益。其他代表曲目包括《The Headmaster Ritual》《I Want the One I Can’t Have》《That Joke Isn’t Funny Anymore》。该作在英国专辑榜上获得第一名，巩固了乐队在独立音乐界的地位。',0,'2025-12-08',3,'Rough Trade唱片','covers/403-The_Smiths-Meat_Is_Murder.jpg','39:47:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1985-02-11','Rock,Pop','The Smiths',145,161,17);
INSERT INTO "albums" VALUES(404,'I’m OK','陶喆','中国','台湾','Pop, Contemporary R&B',3.52,'《I’m OK》是陶喆于1999年6月9日发行的第二张录音室专辑，由他本人担任制作。专辑延续了首张专辑的R&B与流行摇滚融合风格，代表曲目包括《找自己》《普通朋友》《I’m OK》等。该作在华语乐坛引起广泛关注，确立了陶喆作为R&B与流行跨界代表人物的地位。',0,'2025-12-08',1,'滚石唱片','covers/404-陶喆-I’m_OK.jpg','46:00:00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'1999-06-09','Pop,R&B','陶喆',299,222,25);
